/** A file in a flattened tree. */
export interface FileEntry {
  mode: string;
  oid: string;
}

/** Lists every file (non-tree entry) under a tree, keyed by its full path. */
export function flattenTree(gitDir: string, oid: string, prefix = "", into = new Map<string, FileEntry>()): Map<string, FileEntry> {
  for (const entry of readTree(gitDir, oid)) {
    const fullPath = prefix + entry.name;
    if (entry.mode === MODE_TREE) flattenTree(gitDir, entry.oid, `${fullPath}/`, into);
    else into.set(fullPath, { mode: entry.mode, oid: entry.oid });
  }
  return into;
}

/** Writes the trees for a set of files (keyed by full path) and returns the root tree's ID. */
export function writeTreeFromFiles(gitDir: string, files: Iterable<[string, FileEntry]>): string {
  interface Dir {
    files: TreeEntry[];
    dirs: Map<string, Dir>;
  }
  const root: Dir = { files: [], dirs: new Map() };
  for (const [filePath, file] of files) {
    const parts = filePath.split("/");
    const name = parts.pop() as string;
    let dir = root;
    for (const part of parts) {
      let child = dir.dirs.get(part);
      if (!child) {
        child = { files: [], dirs: new Map() };
        dir.dirs.set(part, child);
      }
      dir = child;
    }
    dir.files.push({ mode: file.mode, name, oid: file.oid });
  }
  const write = (dir: Dir): string => {
    const entries = [...dir.files];
    for (const [name, child] of dir.dirs) entries.push({ mode: MODE_TREE, name, oid: write(child) });
    return writeObject(gitDir, "tree", serializeTree(entries));
  };
  return write(root);
}
const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** Formats a date like the real git's default date format: "Tue Nov 14 22:13:20 2023 +0000". */
export function formatDefaultDate(timestamp: number, tz: string): string {
  // The real git reads the timezone as a decimal number (e.g. -700) and prints it with "%+05d".
  const tzValue = Number.parseInt(tz, 10) || 0;
  const offsetMinutes = Math.trunc(tzValue / 100) * 60 + (tzValue % 100);
  const date = new Date((timestamp + offsetMinutes * 60) * 1000);
  const pad = (n: number): string => String(n).padStart(2, "0");
  const time = `${pad(date.getUTCHours())}:${pad(date.getUTCMinutes())}:${pad(date.getUTCSeconds())}`;
  const zone = `${tzValue < 0 ? "-" : "+"}${String(Math.abs(tzValue)).padStart(4, "0")}`;
  return `${WEEKDAYS[date.getUTCDay()]} ${MONTHS[date.getUTCMonth()]} ${date.getUTCDate()} ${time} ${date.getUTCFullYear()} ${zone}`;
