 * Keys are normalized to "section.key" or "section.subsection.key", with the section and the key
 * lowercased, as the real git does. Later files override earlier ones.
 */
export class Config {
  private readonly values = new Map<string, string[]>();

  /** The last value of a key; a key given without "= value" has the value "true". */
  get(key: string): string | undefined {
    return this.values.get(normalizeKey(key))?.at(-1);
  }

  getBool(key: string, defaultValue: boolean): boolean {
    const value = this.get(key);
    if (value === undefined) return defaultValue;
    const lower = value.toLowerCase();
    if (["true", "yes", "on", "1"].includes(lower)) return true;
    if (["false", "no", "off", "0", ""].includes(lower)) return false;
    return defaultValue;
  }

  /** Adds the entries of a config file; a missing file is ignored. */
  addFile(file: string): void {
    let text: string;
    try {
      text = fs.readFileSync(file, "utf8");
    } catch {
      return;
    }
    for (const [key, value] of parseConfig(text)) {
      const values = this.values.get(key) ?? [];
      values.push(value);
      this.values.set(key, values);
    }
  }
}

function normalizeKey(key: string): string {
  const first = key.indexOf(".");
  const last = key.lastIndexOf(".");
  if (first < 0) return key.toLowerCase();
  const section = key.slice(0, first).toLowerCase();

