import fs from "node:fs";
import path from "node:path";
import type { CommandContext } from "../cli/context.ts";
import { usageError } from "../cli/errors.ts";
import { hasOption, parseOptions } from "../cli/options.ts";
import { identFor } from "../core/ident/ident.ts";
import { indexPath, readIndex, writeIndex, type Index } from "../core/index/index-file.ts";
import { formatIdent, readCommit, serializeCommit } from "../core/objects/commit.ts";
import { writeObject } from "../core/objects/store.ts";
import { writeTreeFromFiles } from "../core/objects/tree.ts";
import { HEADS_PREFIX, readHead, resolveHead, writeRef } from "../core/refs/refs.ts";
import type { Repository } from "../core/repo/repository.ts";
import { requireRepository } from "../core/repo/repository.ts";
import { Abbreviator } from "../core/revision/abbrev.ts";
import { indexFiles } from "../core/status/changes.ts";
import { hashWorktreeFile, toIndexEntry } from "../core/worktree/files.ts";

/** Joins `-m` values the way the real git does: each one becomes its own paragraph. */
function joinMessages(messages: readonly string[]): string {
  let text = "";
  for (const message of messages) {
    if (text !== "") text += "\n";
    text += message;
    if (!text.endsWith("\n")) text += "\n";
  }
  return text;
}

/**
 * The real git's "whitespace" cleanup: strips trailing whitespace from each line, collapses runs
 * of blank lines, and drops blank lines at the start and the end.
 */
export function cleanupMessage(text: string): string {
  const lines = text.split("\n").map((line) => line.replace(/\s+$/, ""));
  const kept: string[] = [];
  for (const line of lines) {
    if (line === "" && (kept.length === 0 || kept.at(-1) === "")) continue;
    kept.push(line);
  }
  while (kept.at(-1) === "") kept.pop();
  return kept.length === 0 ? "" : `${kept.join("\n")}\n`;
}

/** Updates the index with the working tree's version of every tracked file (`commit -a`). */
function stageTrackedFiles(repo: Repository, index: Index): void {
  const filemode = repo.config.getBool("core.filemode", true);
  for (const entry of index.list()) {
    const file = hashWorktreeFile(repo.gitDir, path.join(repo.workTree, entry.path), { filemode, previousMode: entry.mode, write: true });
    if (file) index.set(toIndexEntry(entry.path, file));
    else index.delete(entry.path);
  }
}

export function commit(ctx: CommandContext): number {
  const parsed = parseOptions(ctx.args, [
    { name: "message", short: "m", long: "message", takesValue: true },
    { name: "all", short: "a", long: "all" },
  ]);
  if (parsed.positionals.length > 0) throw usageError("committing only some paths is not supported");
  const repo = requireRepository(ctx.cwd, ctx.env);
  const index = readIndex(repo.gitDir);
  const all = hasOption(parsed, "all");
  if (all) stageTrackedFiles(repo, index);

  const tree = writeTreeFromFiles(repo.gitDir, indexFiles(index));
  // Without -a the real git refreshes and writes the index even when the commit fails.
  if (!all && (index.changed || !fs.existsSync(indexPath(repo.gitDir)))) writeIndex(repo.gitDir, index);

  const parent = resolveHead(repo.gitDir);
  const parentTree = parent === null ? null : readCommit(repo.gitDir, parent)?.tree;
  if (tree === parentTree || (parent === null && index.size === 0)) {
    ctx.stdout("nothing to commit, working tree clean\n");
    return 1;
  }
  const message = cleanupMessage(joinMessages(parsed.options.get("message") ?? []));
  if (message === "") {
    ctx.stderr("Aborting commit due to empty commit message.\n");
    return 1;
  }

  const oid = writeObject(
    repo.gitDir,
    "commit",
    serializeCommit({
      tree,
      parents: parent === null ? [] : [parent],
      author: formatIdent(identFor("AUTHOR", repo, ctx.env)),
      committer: formatIdent(identFor("COMMITTER", repo, ctx.env)),
      message,
    }),
  );
  const head = readHead(repo.gitDir);
  writeRef(repo.gitDir, head.kind === "branch" ? head.ref : "HEAD", oid);
  if (all) writeIndex(repo.gitDir, index);

  const where = head.kind === "branch" ? head.ref.replace(HEADS_PREFIX, "") : "detached HEAD";
  const root = parent === null ? " (root-commit)" : "";
  ctx.stdout(`[${where}${root} ${new Abbreviator(repo.gitDir).abbreviate(oid)}] ${message.split("\n")[0]}\n`);
  return 0;
}
EOF

cat > src/commands/rev-parse.ts <<'EOF'
import fs from "node:fs";
import path from "node:path";
import type { CommandContext } from "../cli/context.ts";
import { fatal } from "../cli/errors.ts";
import { requireRepository } from "../core/repo/repository.ts";
import { resolveRevision } from "../core/revision/resolve.ts";

/**
 * `git rev-parse <arg>...`: prints the object ID of each revision. Like the real git, the first
 * argument that is not a revision starts the file arguments: every argument from there on is
 * printed as is, and must name an existing path (unless it comes after "--").
 */
export function revParse(ctx: CommandContext): number {
  const repo = requireRepository(ctx.cwd, ctx.env);
  let inFiles = false;
  for (const [i, arg] of ctx.args.entries()) {
    if (arg === "--") {
      ctx.stdout(`${[arg, ...ctx.args.slice(i + 1)].join("\n")}\n`);
      return 0;
    }
    if (arg.startsWith("-")) {
      ctx.stdout(`${arg}\n`);
      continue;
    }
    const oid = inFiles ? null : resolveRevision(repo.gitDir, arg);
    if (oid !== null) {
      ctx.stdout(`${oid}\n`);
      continue;
    }
    ctx.stdout(`${arg}\n`);
    if (!fs.existsSync(path.resolve(ctx.cwd, arg)) && !isSymlink(path.resolve(ctx.cwd, arg))) {
      throw fatal(
        inFiles
          ? `${arg}: no such path in the working tree.`
          : `ambiguous argument '${arg}': unknown revision or path not in the working tree.`,
      );
    }
    inFiles = true;
  }
  return 0;
}

function isSymlink(absPath: string): boolean {
  try {
    return fs.lstatSync(absPath).isSymbolicLink();
  } catch {
    return false;
  }
}
EOF

cat > src/commands/log.ts <<'EOF'
import type { CommandContext } from "../cli/context.ts";
import { fatal } from "../cli/errors.ts";
import { formatDefaultDate } from "../cli/date.ts";
import { parseIdent, type Commit } from "../core/objects/commit.ts";
import { HEADS_PREFIX, readHead, resolveHead } from "../core/refs/refs.ts";
import { requireRepository } from "../core/repo/repository.ts";
import { Abbreviator } from "../core/revision/abbrev.ts";
import { resolveCommit } from "../core/revision/resolve.ts";
import { walkHistory } from "../core/revision/walk.ts";

interface LogOptions {
  oneline: boolean;
  maxCount: number;
  revisions: string[];
}

function parseCount(text: string): number {
  if (!/^\s*[+-]?\d+$/.test(text)) throw fatal(`'${text}': not an integer`);
  const count = Number(text);
  return count < 0 ? Infinity : count;
}

/** Parses the arguments like the real git's revision options, which have their own error messages. */
function parseLogArgs(args: readonly string[]): LogOptions {
  const options: LogOptions = { oneline: false, maxCount: Infinity, revisions: [] };
  for (let i = 0; i < args.length; i++) {
    const arg = args[i] as string;
    if (arg === "--oneline") {
      options.oneline = true;
    } else if (arg === "-n" || arg === "--max-count") {
      const value = args[++i];
      if (value === undefined) throw fatal(`${arg} requires an argument`, "error");
      options.maxCount = parseCount(value);
    } else if (arg.startsWith("--max-count=")) {
      options.maxCount = parseCount(arg.slice("--max-count=".length));
    } else if (arg.startsWith("-n")) {
      options.maxCount = parseCount(arg.slice(2));
    } else if (/^-\d+$/.test(arg)) {
      options.maxCount = parseCount(arg.slice(1));
    } else if (arg.startsWith("-")) {
      throw fatal(`unrecognized argument: ${arg}`);
    } else {
      options.revisions.push(arg);
    }
  }
  return options;
}

/** The message lines without the blank lines at the start and the end. */
function messageLines(commit: Commit): string[] {
  const lines = commit.message.split("\n").map((line) => line.trimEnd());
  while (lines[0] === "") lines.shift();
  while (lines.at(-1) === "") lines.pop();
  return lines;
}

/** The subject: the lines of the first paragraph, joined with spaces. */
function subject(lines: readonly string[]): string {
  const end = lines.indexOf("");
  return (end < 0 ? lines : lines.slice(0, end)).map((line) => line.trim()).join(" ");
}

export function log(ctx: CommandContext): number {
  const repo = requireRepository(ctx.cwd, ctx.env);
  const options = parseLogArgs(ctx.args);
  const starts: string[] = [];
  for (const revision of options.revisions) {
    const oid = resolveCommit(repo.gitDir, revision);
    if (oid === null) throw fatal(`ambiguous argument '${revision}': unknown revision or path not in the working tree.`);
    starts.push(oid);
  }
  if (options.revisions.length === 0) {
    const head = resolveHead(repo.gitDir);
    if (head === null) {
      const current = readHead(repo.gitDir);
      const name = current.kind === "branch" ? current.ref.replace(HEADS_PREFIX, "") : "HEAD";
      throw fatal(`your current branch '${name}' does not have any commits yet`);
    }
    starts.push(head);
  }

  const abbreviator = new Abbreviator(repo.gitDir);
  const entries: string[] = [];
  for (const { oid, commit } of walkHistory(repo.gitDir, starts)) {
    if (entries.length >= options.maxCount) break;
    const lines = messageLines(commit);
    if (options.oneline) {
      entries.push(`${abbreviator.abbreviate(oid)} ${subject(lines)}\n`);
      continue;
    }
    const author = parseIdent(commit.author);
    const body = lines.map((line) => (line === "" ? "    \n" : `    ${line}\n`)).join("");
    entries.push(`commit ${oid}\nAuthor: ${author.name} <${author.email}>\nDate:   ${formatDefaultDate(author.timestamp, author.tz)}\n\n${body}`);
  }
  ctx.stdout(entries.join(options.oneline ? "" : "\n"));
  return 0;
}
EOF
