import { ExitError } from "./cli/errors.ts";
import type { CommandContext } from "./cli/context.ts";
import { commands } from "./commands/registry.ts";

function main(argv: string[]): number {
  const [name, ...args] = argv;
  if (name === undefined) {
    process.stderr.write("usage: tgit <command> [<args>]\n");
    return 1;
  }
  const run = commands.get(name);
  if (!run) {
    process.stderr.write(`tgit: '${name}' is not a git command. See 'tgit --help'.\n`);
    return 1;
  }
  const ctx: CommandContext = {
    args,
    cwd: process.cwd(),
    env: process.env,
    stdout: (text) => process.stdout.write(text),
    stderr: (text) => process.stderr.write(text),
  };
  try {
    return run(ctx);
  } catch (error) {
    if (error instanceof ExitError) {
      process.stderr.write(`${error.message}\n`);
      return error.code;
    }
    throw error;
  }
}

process.exitCode = main(process.argv.slice(2));
import type { CommandRun } from "../cli/context.ts";
import { add } from "./add.ts";
import { branch } from "./branch.ts";
import { catFile } from "./cat-file.ts";
import { commit } from "./commit.ts";
import { hashObject } from "./hash-object.ts";
import { init } from "./init.ts";
import { log } from "./log.ts";
import { lsFiles } from "./ls-files.ts";
import { revParse } from "./rev-parse.ts";
import { status } from "./status.ts";
import { switchBranch } from "./switch.ts";

export const commands = new Map<string, CommandRun>([
  ["add", add],
  ["branch", branch],
  ["cat-file", catFile],
  ["commit", commit],
  ["hash-object", hashObject],
  ["init", init],
  ["log", log],
  ["ls-files", lsFiles],
  ["rev-parse", revParse],
  ["status", status],
  ["switch", switchBranch],
]);
import fs from "node:fs";
import path from "node:path";
import type { CommandContext } from "../cli/context.ts";
import { fatal } from "../cli/errors.ts";
import { hasOption, parseOptions } from "../cli/options.ts";
import { hashObject as hashBlob, writeObject } from "../core/objects/store.ts";
import { requireRepository } from "../core/repo/repository.ts";

export function hashObject(ctx: CommandContext): number {
  const parsed = parseOptions(ctx.args, [{ name: "write", short: "w" }]);
  const write = hasOption(parsed, "write");
  // Hashing works outside a repository; writing needs one.
  const gitDir = write ? requireRepository(ctx.cwd, ctx.env).gitDir : null;

  for (const file of parsed.positionals) {
    let content: Buffer;
    try {
      content = fs.readFileSync(path.resolve(ctx.cwd, file));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "EISDIR") throw fatal(`Unable to hash ${file}`);
      throw fatal(`could not open '${file}' for reading: No such file or directory`);
    }
    ctx.stdout(`${gitDir ? writeObject(gitDir, "blob", content) : hashBlob("blob", content)}\n`);
  }
  return 0;
}

